/* Card set: Potatoes (built from the approved roster-final.csv by the Potatoes build).
   350 cards: Varieties, Preparations, Chips & Fries, History & Lore, Potato Things.
   Art: real photography via Wikimedia Commons (Special:FilePath, width=1024). */
CardSets.register({"id":"potatoes","name":"Potatoes","code":"SPUD","description":"350 cards celebrating the world's most committed vegetable — 120 varieties, 92 ways to cook it, 50 chips and fries, 49 moments in potato history, and 39 things potatoes have powered, flavoured or been carved into.","theme":{"primary":"#6b4a2b","secondary":"#d9a441","artBackground":"#241a12","artFit":"cover"},"pack":{"name":"Potatoes Pack","emblem":"🥔","skin":"potatoes","slots":[{"count":5,"label":"Common","odds":{"common":100}},{"count":2,"label":"Uncommon","odds":{"uncommon":100}},{"count":1,"label":"Wild card","odds":{"common":55,"uncommon":30,"rare":12,"epic":3}},{"count":1,"label":"Rare or better (guaranteed)","odds":{"rare":81.8,"epic":14,"legendary":4,"chase":0.2}}]},"cards":[{"name":"A Single Potato","rarity":"chase","id":"a-single-potato","subtitle":"Preparation","details":"It is a potato.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato_(3780830486).jpg?width=1024"},{"name":"La Bonnotte","rarity":"chase","id":"la-bonnotte","subtitle":"Variety","details":"From France's Noirmoutier island: hand-harvested, seaweed-fed, and among the most expensive potatoes on Earth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pomme_de_terre_variété_bonnotte.JPG?width=1024"},{"name":"Mr. Potato Head","rarity":"chase","id":"mr-potato-head","subtitle":"Potato Thing","details":"The 1952 original was only plastic face parts — you supplied a real potato from the kitchen. First toy ever advertised on TV.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mr%20Potato%20Head%201952.jpg?width=1024"},{"name":"Potato-Powered Web Server","rarity":"chase","id":"potato-powered-web-server","subtitle":"Potato Thing","details":"In 2000, pranksters claimed 12 potatoes powered a web server running a stripped-down 386. The BBC and Slashdot fell for it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Motherboard%20Intel%20386.jpg?width=1024"},{"name":"Pringles","rarity":"chase","id":"pringles","subtitle":"Chips & Fries","details":"P&G argued Pringles weren't crisps to dodge UK tax. In 2009 the Court of Appeal ruled: at 42% potato, they legally are.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_Pringles_Salt_%26_Vinegar_chips.jpg?width=1024"},{"name":"Russet Burbank","rarity":"chase","id":"russet-burbank","subtitle":"Variety","details":"North America's most-grown potato: brown netted skin, dry mealy flesh, born for baking and fries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Russet_potato.jpg?width=1024"},{"name":"Tater Tots","rarity":"chase","id":"tater-tots","subtitle":"Chips & Fries","details":"Ore-Ida invented tots in 1953 from leftover potato scraps; 'Tater Tot' is still their trademark, whatever your menu says.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Burger_and_tater_tots.jpg?width=1024"},{"name":"The First Potato in Space","rarity":"chase","id":"the-first-potato-in-space","subtitle":"History & Lore","details":"In 1995, shuttle Columbia's STS-73 crew grew five small potatoes in orbit — the potato became the first vegetable grown in space.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Columbia%20with%20Spacelab%20Module%20LM1.jpg?width=1024"},{"name":"The Potato Eaters","rarity":"chase","id":"the-potato-eaters","subtitle":"History & Lore","details":"Van Gogh's The Potato Eaters (1885), painted in Nuenen, shows a peasant family sharing potatoes by lamplight — his first masterpiece.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Potato%20Eaters%20-%20Vincent%20Van%20Gogh.jpg?width=1024"},{"name":"Vitelotte","rarity":"chase","id":"vitelotte","subtitle":"Variety","details":"Gourmet French blue-violet potato, cultivated since at least the early 1800s; the flesh is marbled purple.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vittelotte_noir.jpg?width=1024"},{"name":"A Population Never Recovered","rarity":"legendary","id":"a-population-never-recovered","subtitle":"History & Lore","details":"Ireland held 8.2 million people in 1841. After famine deaths and generations of emigration, the island has never matched it since.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Achill%20Island%20-%20Deserted%20Village%20-%20Cottage%20Ruins%20-%20geograph.org.uk%20-%203759592.jpg?width=1024"},{"name":"Adirondack Blue","rarity":"legendary","id":"adirondack-blue","subtitle":"Variety","details":"Released by Cornell University breeders in 2003; its skin and flesh are a deep blue-purple, even before cooking.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Adirondack_Blue.jpg?width=1024"},{"name":"Adirondack Red","rarity":"legendary","id":"adirondack-red","subtitle":"Variety","details":"Cornell's 2003 companion to Adirondack Blue, with red skin and pink flesh that keeps its color surprisingly well.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/AdirondackRed.gif?width=1024"},{"name":"Aligot","rarity":"legendary","id":"aligot","subtitle":"Preparation","details":"Mashed potato whipped with melted Tomme cheese until it stretches in ribbons; a pilgrim dish from France's Aubrac.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bol_d'aligot.jpg?width=1024"},{"name":"Antoine Parmentier","rarity":"legendary","id":"antoine-parmentier","subtitle":"History & Lore","details":"Fed potatoes as a prisoner of war in Prussia, pharmacist Antoine Parmentier spent his life proving the feared tuber was food.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A.A.%20Parmentier%2C%20RP-P-1911-2604.jpg?width=1024"},{"name":"Big Idaho Potato Truck","rarity":"legendary","id":"big-idaho-potato-truck","subtitle":"Potato Thing","details":"A 28-foot, six-ton russet built for the Idaho Potato Commission's 75th birthday in 2012. It toured seven years, then became an Airbnb.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Big%20Idaho%20Potato%20truck.jpg?width=1024"},{"name":"Bintje","rarity":"legendary","id":"bintje","subtitle":"Variety","details":"Bred in the Netherlands in 1904 by a Frisian schoolmaster and named after his pupil; Europe's classic fry potato.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bintje_b.JPG?width=1024"},{"name":"Brennivín","rarity":"legendary","id":"brennivin","subtitle":"Potato Thing","details":"Iceland's signature schnapps: distilled from fermented potato pulp, flavoured with caraway, nicknamed the Black Death.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bottle%20of%20brennivin.jpg?width=1024"},{"name":"Bryndzové Halušky","rarity":"legendary","id":"bryndzove-halusky","subtitle":"Preparation","details":"Slovakia's national dish: small potato dumplings tossed with bryndza sheep cheese and topped with bacon bits.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/BryndzoveHalusky.JPG?width=1024"},{"name":"Chocolate-Covered Potato Chips","rarity":"legendary","id":"chocolate-covered-potato-chips","subtitle":"Chips & Fries","details":"Salty, crunchy, chocolate-dipped — a North Dakota specialty that Lay's took national with a wavy version in 2013.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lays_Wavy_Chocolate_Covered_Potato_Chips.jpg?width=1024"},{"name":"Disco Fries","rarity":"legendary","id":"disco-fries","subtitle":"Chips & Fries","details":"New Jersey's answer to poutine: fries, brown gravy and melted cheese, popularized by Clifton's Tick Tock Diner in the 1970s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thai_Diner_disco_fries.jpg?width=1024"},{"name":"Funeral Potatoes","rarity":"legendary","id":"funeral-potatoes","subtitle":"Preparation","details":"A Utah casserole of potatoes, cheese, sour cream and a cornflake crust, named for after-funeral luncheons.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Funeralpotatoesdish.JPG?width=1024"},{"name":"Hasselback Potatoes","rarity":"legendary","id":"hasselback-potatoes","subtitle":"Preparation","details":"A baked potato sliced partway through into a fan, from Stockholm's Hasselbacken restaurant in 1953; butter in every slot.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hassel_Back_Spuds-2.jpg?width=1024"},{"name":"Irish Cobbler","rarity":"legendary","id":"irish-cobbler","subtitle":"Variety","details":"American variety from 1876 with white flesh; an early-season classic that is still planted today.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato_cv_IrishCobbler.JPG?width=1024"},{"name":"Kennebec","rarity":"legendary","id":"kennebec","subtitle":"Variety","details":"Bred by the USDA in Maine in 1941; a high-yielding white potato grown for fresh market and chips alike.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Patata_Kennebec.JPG?width=1024"},{"name":"King Edward","rarity":"legendary","id":"king-edward","subtitle":"Variety","details":"Grown in Britain since 1902 and still going: one of the oldest cultivars in commercial production.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/King_Edward.jpg?width=1024"},{"name":"Maris Piper","rarity":"legendary","id":"maris-piper","subtitle":"Variety","details":"Britain's most-grown potato since 1980, introduced in 1966 and bred to resist potato cyst nematode.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Four_Maris_Piper_potatoes,_one_halved.jpg?width=1024"},{"name":"Poitín","rarity":"legendary","id":"poitin","subtitle":"Potato Thing","details":"Ireland's legendary moonshine, traditionally distilled from potatoes. It was outlawed in 1661 and not legal again until 1997.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20Selection%20of%20Legal%20Irish%20and%20Celtic%20Poitin%20or%20Poteen%20Bottles%20Taken%20in%20a%20Poitin%20Bar.jpg?width=1024"},{"name":"Pommes Soufflées","rarity":"legendary","id":"pommes-soufflees","subtitle":"Preparation","details":"Twice-fried potato slices that puff into hollow pillows. A Paris chef stumbled onto them in 1837 cooking for a delayed king.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pommes_soufflée_(31704319754).jpg?width=1024"},{"name":"Poutine","rarity":"legendary","id":"poutine","subtitle":"Preparation","details":"Quebec's fries under cheese curds and brown gravy, born in the 1950s; the curds must squeak or it doesn't count.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alestine's_pulled_pork_poutine.jpg?width=1024"},{"name":"Spice Bag","rarity":"legendary","id":"spice-bag","subtitle":"Chips & Fries","details":"Ireland's cult takeaway: a bag of spiced chips, chicken, peppers and onions, shaken with Chinese five-spice heat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Overseas_Spicebag.jpg?width=1024"},{"name":"The Irish Potato Famine","rarity":"legendary","id":"the-irish-potato-famine","subtitle":"History & Lore","details":"When late blight rotted Ireland's potato crop from 1845, roughly a million people died and a million more emigrated.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Famine%20in%20Ireland%2C%20Funeral%20at%20Skibbereen%20-%20ILN%201847.jpg?width=1024"},{"name":"The Potato War","rarity":"legendary","id":"the-potato-war","subtitle":"History & Lore","details":"The 1778-79 War of the Bavarian Succession saw so much potato-foraging and so little fighting it was nicknamed the Kartoffelkrieg.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Friedrich%20der%20Gro%C3%9Fe%20%281781%20or%201786%29%20-%20Google%20Art%20Project.jpg?width=1024"},{"name":"Vichyssoise","rarity":"legendary","id":"vichyssoise","subtitle":"Preparation","details":"A chilled soup of puréed potato, leek and cream, created in 1917 at New York's Ritz-Carlton by a French-born chef.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vichyssoise.jpg?width=1024"},{"name":"Yukon Gold","rarity":"legendary","id":"yukon-gold","subtitle":"Variety","details":"Developed in Guelph, Canada in the 1960s: thin eye-free skin and yellow flesh that tastes pre-buttered.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Yukon-gold-potatoes.jpg?width=1024"},{"name":"Agria","rarity":"epic","id":"agria","subtitle":"Variety","details":"German variety from 1985 with deep yellow flesh; a fry-shop staple across Europe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Agria.jpg?width=1024"},{"name":"Akvavit","rarity":"epic","id":"akvavit","subtitle":"Potato Thing","details":"Scandinavia's caraway-spiced spirit is distilled from grain or potatoes, then served ice-cold alongside pickled herring.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aalborg%20Akvavit%20bottle%2070cl.jpg?width=1024"},{"name":"All Dressed Chips","rarity":"epic","id":"all-dressed-chips","subtitle":"Chips & Fries","details":"Canada's everything chip: barbecue, sour cream & onion, salt & vinegar and ketchup seasonings on one ridged chip.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/All-dressed_chips.jpg?width=1024"},{"name":"Almond","rarity":"epic","id":"almond","subtitle":"Variety","details":"Sweden's mandelpotatis: a small almond-shaped heirloom, boiled in its skin and prized as a delicacy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Almond_potato.JPG?width=1024"},{"name":"Andean black","rarity":"epic","id":"andean-black","subtitle":"Variety","details":"Andean native potato with near-black skin and golden-yellow flesh, from the highlands where potatoes began.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Andean_black_potato_2.JPG?width=1024"},{"name":"Arran Victory","rarity":"epic","id":"arran-victory","subtitle":"Variety","details":"Scottish variety from 1918 with purple skin over white flesh; the oldest of the Arran varieties still grown.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Home_Grown_'Arran_Victory'_Potatoes.jpg?width=1024"},{"name":"Bacon Cheese Fries","rarity":"epic","id":"bacon-cheese-fries","subtitle":"Chips & Fries","details":"Cheese fries, upgraded with crumbled bacon — the bacon is not a garnish, it's a structural ingredient.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/McDonald%27s_Italia_Fries_Cheese%26Bacon_%28cropped%29.jpg?width=1024"},{"name":"Black '47","rarity":"epic","id":"black-47","subtitle":"History & Lore","details":"1847, the famine's worst year, is remembered as Black '47: the year of fever, evictions and mass emigration from Ireland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Irish%20potato%20famine%20Bridget%20O%27Donnel.jpg?width=1024"},{"name":"Blaue Anneliese","rarity":"epic","id":"blaue-anneliese","subtitle":"Variety","details":"German blue variety: the dark skin hides flesh that stays a dusky violet even after cooking.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kartoffeln_Sorte_Blaue_Anneliese.jpg?width=1024"},{"name":"Blue Congo","rarity":"epic","id":"blue-congo","subtitle":"Variety","details":"Old Scandinavian blue variety, also called Blauer Schwede; the cut flesh is a solid, startling violet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blauer_Schwede_b.JPG?width=1024"},{"name":"Carne Asada Fries","rarity":"epic","id":"carne-asada-fries","subtitle":"Chips & Fries","details":"San Diego's invention: fries buried under carne asada, cheese, guacamole and sour cream — nachos that chose potatoes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tacos_El_Gordo_Carne_Asada_Fries_close_up.jpg?width=1024"},{"name":"Causa","rarity":"epic","id":"causa","subtitle":"Preparation","details":"Peru's causa layers seasoned mashed yellow potato with tuna, chicken or avocado, served cold like a potato cake.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Causa_Peruvian_dish.jpg?width=1024"},{"name":"Cepelinai","rarity":"epic","id":"cepelinai","subtitle":"Preparation","details":"Lithuania's national dish: huge zeppelin-shaped dumplings of raw and cooked potato, stuffed with curd or meat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/020260228_cepelinai.jpg?width=1024"},{"name":"Cheese Fries","rarity":"epic","id":"cheese-fries","subtitle":"Chips & Fries","details":"Fries under a blanket of melted cheese sauce — a ballpark and diner staple where the fries are merely the delivery vehicle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese_Fries.jpg?width=1024"},{"name":"Chorrillana","rarity":"epic","id":"chorrillana","subtitle":"Preparation","details":"Chile's sharing plate of fries buried under sliced meat, sausage, fried onions and eggs. Not a solo dish.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/CHORILLANAS.jpg?width=1024"},{"name":"Chuño, the First Freeze-Dried Food","rarity":"epic","id":"chuno-the-first-freeze-dried-food","subtitle":"History & Lore","details":"Andean farmers freeze-dried potatoes through frosty nights and sunny days, stamping out the water. Chuño keeps for years.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chuno-01.jpg?width=1024"},{"name":"Colcannon","rarity":"epic","id":"colcannon","subtitle":"Preparation","details":"Irish mashed potato folded with kale or cabbage and butter; traditionally served at Halloween with charms hidden inside.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Colcannon_(5532418361).jpg?width=1024"},{"name":"Edzell Blue","rarity":"epic","id":"edzell-blue","subtitle":"Variety","details":"Scottish variety with purple skin and white flesh ringed in violet; an old Angus heirloom.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Edzell_Blue_potato_SASA.jpg?width=1024"},{"name":"Frederick the Great's Potato Edict","rarity":"epic","id":"frederick-the-great-s-potato-edict","subtitle":"History & Lore","details":"Frederick the Great issued some 15 potato decrees; the famous edict of 24 March 1756 ordered Prussians to plant them.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Robert%20Warthm%C3%BCller%20-%20Der%20K%C3%B6nig%20%C3%BCberall%20%281886%29.jpg?width=1024"},{"name":"Gratin Dauphinois","rarity":"epic","id":"gratin-dauphinois","subtitle":"Preparation","details":"From France's Dauphiné: thin potato slices baked slowly in cream and garlic. By tradition, cheese is forbidden.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A_patate_oct_2023_(1).jpg?width=1024"},{"name":"Halal Snack Pack","rarity":"epic","id":"halal-snack-pack","subtitle":"Preparation","details":"Australia's fries under doner meat and cheese with garlic, chilli and barbecue sauces; a takeaway phenomenon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kebab_Snackpack_-_Sydney.JPG?width=1024"},{"name":"Heiderot","rarity":"epic","id":"heiderot","subtitle":"Variety","details":"German red variety; skin and flesh stay a deep rose-red, even in the pan.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Heiderot_festkochend_Barum.jpg?width=1024"},{"name":"Janssons Frestelse","rarity":"epic","id":"janssons-frestelse","subtitle":"Preparation","details":"'Jansson's Temptation': a Swedish Christmas casserole of potato, onion, pickled sprats and cream under breadcrumbs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Janssons_frestelse.jpg?width=1024"},{"name":"Kapsalon","rarity":"epic","id":"kapsalon","subtitle":"Preparation","details":"A Rotterdam tray of fries under döner meat and melted Gouda, blanketed in salad; invented in 2003 by a hairdresser.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kapsalon-Rotterdam.jpg?width=1024"},{"name":"Knish","rarity":"epic","id":"knish","subtitle":"Preparation","details":"A baked or fried dough pocket of seasoned mashed potato, carried from Eastern Europe to New York delis.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Knishes_with_nigella_seed.jpg?width=1024"},{"name":"Papa a la Huancaína","rarity":"epic","id":"papa-a-la-huancaina","subtitle":"Preparation","details":"Peruvian boiled yellow potatoes under a spicy, creamy cheese sauce from Huancayo, served cold with egg and olive.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Arroz_con_pato_y_papa_a_la_huancaina.jpg?width=1024"},{"name":"Papas Arrugadas","rarity":"epic","id":"papas-arrugadas","subtitle":"Preparation","details":"Canary Islands 'wrinkly potatoes', boiled in seawater-strength brine until the skins wrinkle, served with mojo sauce.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mojo_rojo_-_Papas_arrugads.JPG?width=1024"},{"name":"Parmentier's Guarded Field","rarity":"epic","id":"parmentier-s-guarded-field","subtitle":"History & Lore","details":"Parmentier guarded his potato plot by day and left it open at night. Parisians stole the 'precious' crop — and planted it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Centenaire%20de%20Parmentier%2C%20la%20statue%20%C3%A0%20Neuilly%20-%20btv1b9043003k.jpg?width=1024"},{"name":"Pink Fir Apple","rarity":"epic","id":"pink-fir-apple","subtitle":"Variety","details":"Victorian-era French heirloom: pink, knobbly fingerlings with firm, nutty flesh, beloved by chefs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pink_fir-apple_potato.JPG?width=1024"},{"name":"Potato Battery","rarity":"epic","id":"potato-battery","subtitle":"Potato Thing","details":"Copper, zinc and the potato's own phosphoric acid make a cell of about 0.9 volts — enough for an LED or science-fair glory.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato-Battery-5495.jpg?width=1024"},{"name":"Potato Cannon","rarity":"epic","id":"potato-cannon","subtitle":"Potato Thing","details":"PVC pipe, a burst of hairspray and a potato rammed home: combustion spud guns can throw a spud hundreds of metres.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spudguns.jpg?width=1024"},{"name":"Potatoes for Mars","rarity":"epic","id":"potatoes-for-mars","subtitle":"History & Lore","details":"In 2017 the Potato Center and NASA reported potatoes sprouting in Mars-like Peruvian desert soil: a rehearsal for space farms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Planetary%20Analogue.jpg?width=1024"},{"name":"Purple Peruvian","rarity":"epic","id":"purple-peruvian","subtitle":"Variety","details":"Andean heirloom with purple skin and purple flesh, grown in the Peruvian highlands for centuries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/PurplePeruvianPotatoes.jpg?width=1024"},{"name":"Rote Emmalie","rarity":"epic","id":"rote-emmalie","subtitle":"Variety","details":"German variety with pink skin and pink-marbled flesh; the color survives cooking.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rote_Emmalie.jpg?width=1024"},{"name":"Russian blue","rarity":"epic","id":"russian-blue","subtitle":"Variety","details":"Russian variety with blue skin; cut open, the flesh is streaked violet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Russian_Blue_potato.jpg?width=1024"},{"name":"Tornado Potato","rarity":"epic","id":"tornado-potato","subtitle":"Chips & Fries","details":"A South Korean street snack: one whole potato spiral-cut on a skewer, stretched, fried and dusted with seasoning.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Annotopia-Vischering-04672.jpg?width=1024"},{"name":"Violetta","rarity":"epic","id":"violetta","subtitle":"Variety","details":"German blue variety; the whole tuber, skin to core, is a deep blue-violet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/ViolettaIMG_7571.jpg?width=1024"},{"name":"Ajiaco","rarity":"rare","id":"ajiaco","subtitle":"Preparation","details":"Bogotá's chicken and potato soup, made with three kinds of potato, corn and capers, finished with cream.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ajiaco,_El_Colonial,_Nemocón,_Colombia.jpg?width=1024"},{"name":"Aloo Chaat","rarity":"rare","id":"aloo-chaat","subtitle":"Preparation","details":"Delhi street chaat of fried potato cubes tossed with chutneys, yogurt, spices and pomegranate. Sweet, sour, hot, crisp.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aloo_Chaat.jpg?width=1024"},{"name":"Aloo Paratha","rarity":"rare","id":"aloo-paratha","subtitle":"Preparation","details":"Indian flatbread stuffed with spiced mashed potato, rolled, griddled in ghee and served with yogurt and pickle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/\"Amazing_Aloo_Paratha_and_Lovely_Lassi\".jpg?width=1024"},{"name":"Amflora","rarity":"rare","id":"amflora","subtitle":"Variety","details":"BASF's industrial starch potato: approved in Europe in 2010, prohibited by 2013. Bred for factories, not dinner.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Auspflanzung_Schweden_2.jpg?width=1024"},{"name":"Anton de Bary's Proof","rarity":"rare","id":"anton-de-bary-s-proof","subtitle":"History & Lore","details":"In 1861 Anton de Bary proved a microbe caused potato blight, an experiment that helped launch the science of plant diseases.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/1880ca%20deBary%20Ed.Fischer.jpg?width=1024"},{"name":"Bamberger Hörnla","rarity":"rare","id":"bamberger-hornla","subtitle":"Variety","details":"Franconian heirloom shaped like a croissant; its name means 'little horn' and it is a Slow Food favorite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bamberger_Hörnla.JPG?width=1024"},{"name":"Boxty","rarity":"rare","id":"boxty","subtitle":"Preparation","details":"Irish pancakes of grated raw and mashed potato. A rhyme warns that without boxty, you'll never win a husband.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ansolas_boxty.jpg?width=1024"},{"name":"Brændende Kærlighed","rarity":"rare","id":"brndende-krlighed","subtitle":"Preparation","details":"Danish 'burning love': mashed potatoes under fried bacon and caramelised onions. The name is not ironic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brændende_Kærlighed.jpg?width=1024"},{"name":"Charlotte","rarity":"rare","id":"charlotte","subtitle":"Variety","details":"French salad variety from 1981 with firm, fine flesh; the potato-salad standard in France.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Charlotte_potato_SASA.jpg?width=1024"},{"name":"Chili Cheese Fries","rarity":"rare","id":"chili-cheese-fries","subtitle":"Chips & Fries","details":"Cheese fries plus a ladle of chili. Fork required, dignity optional, napkins non-negotiable.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chili_cheese_fries_mexico.jpg?width=1024"},{"name":"Chip Fork","rarity":"rare","id":"chip-fork","subtitle":"Potato Thing","details":"The stubby two-pronged fork handed out with fries in Belgium and the Netherlands. Engineered to be exactly almost long enough.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Frietvorkje.jpg?width=1024"},{"name":"Currywurst with Fries","rarity":"rare","id":"currywurst-with-fries","subtitle":"Chips & Fries","details":"Berlin street food since 1949: bratwurst under curry ketchup, with fries — 'Pommes rot-weiß' if you want mayo too.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Currywurst_%26_Pommes_frites.jpg?width=1024"},{"name":"Ditta","rarity":"rare","id":"ditta","subtitle":"Variety","details":"Austrian salad variety with firm, waxy, deep-yellow flesh that slices cleanly.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kartoffel-Ditta_5236.JPG?width=1024"},{"name":"Draniki","rarity":"rare","id":"draniki","subtitle":"Preparation","details":"Belarus's national dish: finely grated potato pancakes, fried crisp and served with sour cream.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2024.04.19_Potato_Pancakes_Belarusian_Draniki_Restaurants_of_Gostiny_Dwor_Nekhachevo.jpg?width=1024"},{"name":"Duchess Potatoes","rarity":"rare","id":"duchess-potatoes","subtitle":"Preparation","details":"Mashed potato with egg yolk and butter, piped into swirls and baked golden. Mashed potatoes in formal attire.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pommes_duchesse.jpg?width=1024"},{"name":"Désirée","rarity":"rare","id":"desiree","subtitle":"Variety","details":"Dutch variety from 1962 with red skin and firm yellow flesh; a worldwide roasting favorite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Désirée_Potatoes.jpg?width=1024"},{"name":"Early Rose","rarity":"rare","id":"early-rose","subtitle":"Variety","details":"American variety from 1861, bred in Vermont; the ancestor of much of the US potato industry.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato_EarlyRose_sprouts.jpg?width=1024"},{"name":"Fingerling","rarity":"rare","id":"fingerling","subtitle":"Variety","details":"Not one variety but a whole shape: small, finger-like heritage potatoes, waxy and made for roasting whole.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fingerling_Potatoes,_Pike_Place_Market.jpg?width=1024"},{"name":"First Encounter, 1537","rarity":"rare","id":"first-encounter-1537","subtitle":"History & Lore","details":"In 1537, Spanish conquistadors in today's Colombia found villagers' stores of what one account called 'a type of truffle'.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monumento%20%22Gonzalo%20Jim%C3%A9nez%20de%20Quesada%22.jpg?width=1024"},{"name":"Fondant Potatoes","rarity":"rare","id":"fondant-potatoes","subtitle":"Preparation","details":"Cylinders of potato seared in butter, then braised in stock until they melt in the middle. French for 'melting'.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/-2022-03-08_Pan-Roasted_Duck_Breast,_fondant_potato,_wilted_greens,_cherry_sauce,_Trimingham,_Norfolk.JPG?width=1024"},{"name":"France Bans the Potato, 1748","rarity":"rare","id":"france-bans-the-potato-1748","subtitle":"History & Lore","details":"In 1748 the Parlement of Paris banned growing potatoes, blaming them for leprosy. The ban stood for a generation.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jean-Fran%C3%A7ois%20Millet%20-%20Potato%20Planters%20-%20Google%20Art%20Project.jpg?width=1024"},{"name":"Gamjatang","rarity":"rare","id":"gamjatang","subtitle":"Preparation","details":"A Korean stew of pork spine bones and potatoes in a perilla-seed broth; the name literally means 'potato soup'.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gamja-tang_4.jpg?width=1024"},{"name":"German Butterball","rarity":"rare","id":"german-butterball","subtitle":"Variety","details":"Yellow-fleshed heirloom in the German style; the name promises butter and the flesh delivers it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/German_butterball.jpg?width=1024"},{"name":"Golden Wonder","rarity":"rare","id":"golden-wonder","subtitle":"Variety","details":"Scottish variety from 1906, famous for exceptionally floury flesh — a baker and chipper.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Golden_Wonder_potato_SASA.jpg?width=1024"},{"name":"Granola","rarity":"rare","id":"granola","subtitle":"Variety","details":"German all-rounder named Germany's Potato of the Year for 2014, as the sign in its portrait boasts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Granola_b.JPG?width=1024"},{"name":"Huayro","rarity":"rare","id":"huayro","subtitle":"Variety","details":"Peruvian native variety with dry, mealy flesh; a classic of the Andean kitchen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Papa_huayro_1.jpg?width=1024"},{"name":"Hutspot","rarity":"rare","id":"hutspot","subtitle":"Preparation","details":"A Dutch mash of potatoes, carrots and onions, said to date to the 1574 siege of Leiden and still eaten every October 3rd.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2015_0330_Hutspot_karbonade.jpg?width=1024"},{"name":"Inca no Mezame","rarity":"rare","id":"inca-no-mezame","subtitle":"Variety","details":"Japanese variety with intensely yellow, sweet flesh; its name means 'the awakening of the Inca'.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Inca_no_mezame.jpg?width=1024"},{"name":"Jefferson Serves French Fries","rarity":"rare","id":"jefferson-serves-french-fries","subtitle":"History & Lore","details":"Thomas Jefferson served 'potatoes in the French manner' at the White House in 1802, an early American outing for the fry.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/JEFFERSON%2C%20Thomas-President%20%28BEP%20engraved%20portrait%29.jpg?width=1024"},{"name":"John Mitchel's Verdict","rarity":"rare","id":"john-mitchel-s-verdict","subtitle":"History & Lore","details":"Irish writer John Mitchel's 1861 verdict endures: 'The Almighty indeed sent the potato blight, but the English created the Famine.'","image":"https://commons.wikimedia.org/wiki/Special:FilePath/John%20Mitchel%20-%20the%20first%20martyr%20of%20Ireland%20in%20her%20revolution%20of%201848%20LCCN2002707683.jpg?width=1024"},{"name":"Kartoffelklöße","rarity":"rare","id":"kartoffelkloe","subtitle":"Preparation","details":"German potato dumplings, made from raw grated or cooked riced potato depending on the region's fierce opinion.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ente_mit_Thüringer_Klößen_1.JPG?width=1024"},{"name":"Kerrs Pink","rarity":"rare","id":"kerrs-pink","subtitle":"Variety","details":"Scottish variety from 1907 with pink skin and very floury flesh; a staple of Irish and Scottish kitchens.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kerrs_Pink_Kelso_potato_day_at_springwood_park.jpg?width=1024"},{"name":"Ketchup Chips","rarity":"rare","id":"ketchup-chips","subtitle":"Chips & Fries","details":"A Canadian icon since the 1970s: sweet, tangy and guaranteed to stain your fingers traffic-light red.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ketchup_chips.jpg?width=1024"},{"name":"Kettle-Cooked Chips","rarity":"rare","id":"kettle-cooked-chips","subtitle":"Chips & Fries","details":"Cooked in small batches the old way, so they're thicker, darker and crunchier — the kettle style roared back in the 1980s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2020-07-19_12_19_38_A_sample_of_Lay%27s_Kettle_Cooked_Original_potato_chips_in_the_Dulles_section_of_Sterling%2C_Loudoun_County%2C_Virginia.jpg?width=1024"},{"name":"Kitaakari","rarity":"rare","id":"kitaakari","subtitle":"Variety","details":"Japanese variety whose name means 'light of the north'; sweet, bright-yellow flesh from Hokkaido breeding.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato_cv_kitaakari.JPG?width=1024"},{"name":"Linda","rarity":"rare","id":"linda","subtitle":"Variety","details":"German salad variety from 1974; when its official listing lapsed, public outcry famously brought it back.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato_var._Linda_HC1.JPG?width=1024"},{"name":"Loaded Fries","rarity":"rare","id":"loaded-fries","subtitle":"Chips & Fries","details":"The fries stop being a side and become the meal: cheese, bacon, sour cream, scallions, everything.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vegan_BBQ_Boss_Loaded_Waffle_Fries_-_Brewhouse_%26_Kitchen%2C_Worthing_2026-06-08.jpg?width=1024"},{"name":"May Queen","rarity":"rare","id":"may-queen","subtitle":"Variety","details":"One of Japan's two staple table varieties, with smooth skin and pale, fine flesh.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato_cv_MayQueen.jpg?width=1024"},{"name":"Nicola","rarity":"rare","id":"nicola","subtitle":"Variety","details":"German salad variety from the 1970s with firm yellow flesh; a benchmark for waxy potatoes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Solanum_tuberosum_'Nicola',_aardappel.jpg?width=1024"},{"name":"Ozette","rarity":"rare","id":"ozette","subtitle":"Variety","details":"Fingerling brought to the Makah people of Washington in the 1790s — possibly America's oldest potato.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ozette_potato1.jpg?width=1024"},{"name":"Patatas Bravas","rarity":"rare","id":"patatas-bravas","subtitle":"Preparation","details":"Madrid's bar tapa: fried potato chunks under spicy bravas sauce and often aioli. 'Bravas' means fierce.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Patatas_Bravas_-_Terraza.JPG?width=1024"},{"name":"Pompadour","rarity":"rare","id":"pompadour","subtitle":"Variety","details":"French variety named for Madame de Pompadour, with buff skin and firm salad flesh.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pomme_de_terre_\"Pompadour\"_01.jpg?width=1024"},{"name":"Potato Clock","rarity":"rare","id":"potato-clock","subtitle":"Potato Thing","details":"Chain enough potato cells together and you can run a digital clock for weeks. The display is real; the electricity is spuds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%D0%91%D0%B0%D1%82%D0%B0%D1%80%D0%B5%D0%B9%D0%BA%D0%B0%20%D0%B7%20%D0%BA%D0%B0%D1%80%D1%82%D0%BE%D0%BF%D0%BB%D1%96.jpg?width=1024"},{"name":"Potato Grader","rarity":"rare","id":"potato-grader","subtitle":"Potato Thing","details":"The Boggs grader sends tubers rolling over widening gaps; the small ones drop through first. Size order, restored.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Boggs%20Potato%20Grader.jpg?width=1024"},{"name":"Potato Rumbler","rarity":"rare","id":"potato-rumbler","subtitle":"Potato Thing","details":"The industrial peeler: spuds tumble against abrasive drum walls while water blasts the skins off. Hundreds peeled per hour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kartoffelsch%C3%A4lmaschine.jpg?width=400"},{"name":"Potato Skins","rarity":"rare","id":"potato-skins","subtitle":"Chips & Fries","details":"Unpeeled potato halves, hollowed and baked again with cheddar, bacon and green onions — a 1970s American pub classic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato_skins_arranged_on_a_plate_as_an_appetizer.jpg?width=1024"},{"name":"Potato Tump","rarity":"rare","id":"potato-tump","subtitle":"Potato Thing","details":"Also called a clamp: spuds heaped under straw and soil keep all winter outdoors. It looks like a grassy hill. It is lunch.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato%20tump%20-%20geograph.org.uk%20-%20190582.jpg?width=1024"},{"name":"Potato Vodka","rarity":"rare","id":"potato-vodka","subtitle":"Potato Thing","details":"Poland's Luksusowa has been distilled from potatoes since 1928. Spud vodka is prized for its creamy, almost buttery mouthfeel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Luksusowa%20Vodka%20700ml.jpg?width=1024"},{"name":"Purple Potato Chips","rarity":"rare","id":"purple-potato-chips","subtitle":"Chips & Fries","details":"Made from purple potatoes, so the chips come out inky blue-black and nutty — no food coloring, just genetics.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Black_Potato_chips_20210406.jpg?width=1024"},{"name":"Ratte","rarity":"rare","id":"ratte","subtitle":"Variety","details":"French heritage fingerling, prized by chefs for firm flesh and a chestnut-like flavor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/La_Ratte.jpg?width=1024"},{"name":"Rösti","rarity":"rare","id":"rosti","subtitle":"Preparation","details":"A Swiss cake of grated potato fried in butter until a single golden crust forms; once a Bernese farmers' breakfast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cervelat_con_rösti_y_ensalada.jpg?width=1024"},{"name":"Salt Potatoes","rarity":"rare","id":"salt-potatoes","subtitle":"Preparation","details":"Syracuse salt potatoes: small potatoes boiled in heavily salted water until creamy inside, drowned in butter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Salt_Potatoes.jpg?width=1024"},{"name":"Smiley Fries","rarity":"rare","id":"smiley-fries","subtitle":"Chips & Fries","details":"Mashed potato shaped into grinning faces and fried golden; McCain sells them as Smiles, and kids plan meals around them.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/POTATO_SMILEYS.jpg?width=1024"},{"name":"Starch Packing Peanuts","rarity":"rare","id":"starch-packing-peanuts","subtitle":"Potato Thing","details":"Loose-fill chips foamed from potato starch instead of polystyrene. Dropped some? They melt in water and go in the compost.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/St%C3%A4rke-Packstoff%20P%C3%B6mpel%20CG.jpg?width=1024"},{"name":"Tartiflette","rarity":"rare","id":"tartiflette","subtitle":"Preparation","details":"A Savoy alpine bake of potatoes, Reblochon cheese, lardons and onion, invented to sell more Reblochon. It worked.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tartiflette_2.jpg?width=1024"},{"name":"The Blight Itself","rarity":"rare","id":"the-blight-itself","subtitle":"History & Lore","details":"Phytophthora infestans — 'plant destroyer' in Greek — is a water mould, not a true fungus. It reached Europe in 1845.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Late%20blight%20on%20potato%20leaf%202.jpg?width=1024"},{"name":"The Coffin Ships","rarity":"rare","id":"the-coffin-ships","subtitle":"History & Lore","details":"Famine emigrants crossed the Atlantic in 'coffin ships'; thousands who fled hunger died of fever at Canada's Grosse Isle in 1847.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hangar%20surintendant%20Grosse%20Ile.jpg?width=1024"},{"name":"The Giant Potato","rarity":"rare","id":"the-giant-potato","subtitle":"Potato Thing","details":"A giant russet stands guard outside the Idaho Potato Museum in Blackfoot, Idaho — a compulsory photo stop on the spud pilgrimage.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/IdahoPotatoMuseumPotato.jpg?width=1024"},{"name":"The Potato Museum","rarity":"rare","id":"the-potato-museum","subtitle":"History & Lore","details":"Blackfoot's Idaho Potato Museum opened in 1988 inside a 1913 railroad depot. A giant baked potato stands guard outside.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/IdahoPotatoMuseum.jpg?width=1024"},{"name":"Tortilla Española","rarity":"rare","id":"tortilla-espanola","subtitle":"Preparation","details":"Spain's potato and egg omelette, thick and slow-cooked in olive oil. The onion question divides the nation.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/-2019-05-29_Spanish_Omelette,_Cromer_(3).JPG?width=1024"},{"name":"Agata","rarity":"uncommon","id":"agata","subtitle":"Variety","details":"Dutch variety from 1976 with yellow skin and flesh; one of the most widely grown table potatoes in Europe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato_variety_Agata.jpg?width=1024"},{"name":"Allians","rarity":"uncommon","id":"allians","subtitle":"Variety","details":"German salad variety from 2003 with firm, waxy flesh that holds together in potato salad.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kartoffel_Allians_03_(fcm).jpg?width=1024"},{"name":"Aloo Gobi","rarity":"uncommon","id":"aloo-gobi","subtitle":"Preparation","details":"A dry Indian curry of potato and cauliflower with turmeric and spices; the potato's most famous duet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aloo_Gobi_Masala_-_Mohali_2016-08-07_8551.JPG?width=1024"},{"name":"Aloo Tikki","rarity":"uncommon","id":"aloo-tikki","subtitle":"Preparation","details":"Spiced potato patties from North India, fried crisp and piled with chutneys, yogurt and sev in chaat stalls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aloo_Ki_Tikki_02.jpg?width=1024"},{"name":"Anuschka","rarity":"uncommon","id":"anuschka","subtitle":"Variety","details":"German variety with smooth golden skin and firm flesh; a popular modern salad potato.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anuschka.jpg?width=1024"},{"name":"Anya","rarity":"uncommon","id":"anya","subtitle":"Variety","details":"Scottish variety from 1996, a cross of Désirée and Pink Fir Apple, named after Lady Sainsbury.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anya_potato_SASA.jpg?width=1024"},{"name":"Asparges","rarity":"uncommon","id":"asparges","subtitle":"Variety","details":"The Danish 'asparagus potato': a slim fingerling type with waxy flesh, steamed whole for summer dinners.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Asparges_potato_SASA.jpg?width=1024"},{"name":"Atlanta","rarity":"uncommon","id":"atlanta","subtitle":"Variety","details":"German variety with speckled, russeted skin; the tubers look dusted with cocoa in their portraits.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kartoffel_Atlanta.JPG?width=1024"},{"name":"Atlantic","rarity":"uncommon","id":"atlantic","subtitle":"Variety","details":"American variety from 1978 with white flesh; for decades the standard potato for US potato chips.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Atlantic_potato_SASA.jpg?width=1024"},{"name":"Batata Harra","rarity":"uncommon","id":"batata-harra","subtitle":"Preparation","details":"Lebanese 'spicy potatoes': cubes fried with garlic, chilli, red pepper and coriander in olive oil.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Batata_harra.jpg?width=1024"},{"name":"Bauernfrühstück","rarity":"uncommon","id":"bauernfruhstuck","subtitle":"Preparation","details":"A German farmer's breakfast of fried potatoes, eggs, bacon and onion set like an omelette. Built for field work.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/1._Wikipedia_Stammtisch_Berlin_Nordost_004.jpg?width=1024"},{"name":"Belgian Frites","rarity":"uncommon","id":"belgian-frites","subtitle":"Chips & Fries","details":"Belgian frites are fried twice — once to cook, once to crisp — then served in a paper cone, traditionally with mayonnaise.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Flickr_-_cyclonebill_-_Pommes_frites_med_salatmayonnaise.jpg?width=1024"},{"name":"Bellarosa","rarity":"uncommon","id":"bellarosa","subtitle":"Variety","details":"Eastern European variety with red skin and yellow flesh, bred for drought tolerance.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bellarosa.jpg?width=1024"},{"name":"Bratkartoffeln","rarity":"uncommon","id":"bratkartoffeln","subtitle":"Preparation","details":"German fried potatoes, sliced and crisped in a pan with bacon and onion; the correct use of yesterday's boiled potatoes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/02021_0368_Schnitzel_mit_Bratkartoffeln_und_Salat,_Beskiden.jpg?width=1024"},{"name":"British Chips","rarity":"uncommon","id":"british-chips","subtitle":"Chips & Fries","details":"Cut thick and fried soft, British chips have been served with battered fish since the 1860s, ideally doused in salt and vinegar.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fish_and_chips_plate_with_peas.jpg?width=1024"},{"name":"British Queen","rarity":"uncommon","id":"british-queen","subtitle":"Variety","details":"Scottish variety from 1894; once among Britain's most important maincrops.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/British_Queen_potato_SASA.jpg?width=1024"},{"name":"Bubble and Squeak","rarity":"uncommon","id":"bubble-and-squeak","subtitle":"Preparation","details":"English fried leftovers: potato and cabbage (or any Sunday veg) mashed and sizzled in a pan until it squeaks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/-2021-12-03_Pan_fried_Bubble_and_squeak,_Trimingham,_Norfolk_(1).JPG?width=1024"},{"name":"Cajun Fries","rarity":"uncommon","id":"cajun-fries","subtitle":"Chips & Fries","details":"Dusted with Louisiana-style Cajun spice — paprika, cayenne, garlic — the way Popeyes made famous.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cajun_fries_from_Popeyes_Louisiana_Kitchen%2C_Stratford%2C_Ontario%2C_2025-08-04.jpg?width=1024"},{"name":"Chiloé","rarity":"uncommon","id":"chiloe","subtitle":"Variety","details":"Native potatoes of Chile's Chiloé Archipelago, one of the potato's ancestral homes, in dozens of colors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Papas_de_colores_de_Chiloe.jpg?width=1024"},{"name":"Cieza de León's Chronicle","rarity":"uncommon","id":"cieza-de-leon-s-chronicle","subtitle":"History & Lore","details":"Pedro Cieza de León described the potato in print in his 1553 Chronicle of Peru, among the first Europeans to do so.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pedro%20Cieza%20de%20Le%C3%B3n%2C%201553.%20.jpg?width=1024"},{"name":"Colette","rarity":"uncommon","id":"colette","subtitle":"Variety","details":"German variety from 1995 with yellow skin and flesh, bred as an early table potato.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Colette.jpg?width=1024"},{"name":"Corte","rarity":"uncommon","id":"corte","subtitle":"Variety","details":"Native variety from Andahuaylas, Peru; cut open, its flesh is striped pink like marble.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Papa_andina,_pomme_de_terre,Gonterre_2007_1337.jpg?width=1024"},{"name":"Cottage Fries","rarity":"uncommon","id":"cottage-fries","subtitle":"Chips & Fries","details":"Round, pan-fried slices said to be named for cottage roof shingles, which the overlapping golden rounds resemble.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potatoes_lyonnaise.JPG?width=1024"},{"name":"Crisp Sandwich","rarity":"uncommon","id":"crisp-sandwich","subtitle":"Chips & Fries","details":"Britain and Ireland's carb-on-carb masterpiece: crisps as the ONLY sandwich filling, buttered bread, pressed flat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/White_Bread_Crisp_Sandwich_.jpg?width=1024"},{"name":"Cultra","rarity":"uncommon","id":"cultra","subtitle":"Variety","details":"Irish-bred variety from Loughgall; at home it is sold simply as 'Garden Potatoes'.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2_kg_bag_of_Cultra_variety_potatoes.jpg?width=1024"},{"name":"Curly Fries","rarity":"uncommon","id":"curly-fries","subtitle":"Chips & Fries","details":"Cut with a spiral slicer and coated in seasoned batter, so every fry is a crispy, spiced spring.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Curly_fries_%283764323218%29.jpg?width=1024"},{"name":"Curry Chips","rarity":"uncommon","id":"curry-chips","subtitle":"Chips & Fries","details":"An Irish and British chip-shop icon: thick chips drowned in mild, sweet curry sauce. Best eaten with a wooden fork.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Curry_chips.jpg?width=1024"},{"name":"Declared Edible, 1772","rarity":"uncommon","id":"declared-edible-1772","subtitle":"History & Lore","details":"In 1772, after Parmentier's campaign, the Paris Faculty of Medicine officially declared potatoes fit for people to eat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Solanum%20tuberosum%205Dsr%202411.jpg?width=1024"},{"name":"Dejima","rarity":"uncommon","id":"dejima","subtitle":"Variety","details":"Japanese variety grown around Nagasaki, named for the old Dutch trading post of Dejima.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato_cv_Dejima.jpg?width=1024"},{"name":"Di San Xian","rarity":"uncommon","id":"di-san-xian","subtitle":"Preparation","details":"'Three treasures of the earth' from Northeast China: fried potato, eggplant and peppers in a glossy sauce.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Beijing_Garden_-_Vegetables_(5276052768).jpg?width=1024"},{"name":"Doré","rarity":"uncommon","id":"dore","subtitle":"Variety","details":"Old Dutch golden variety; its name is French for 'golden', which its skin and flesh both are.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aardappel_'Doré'_(Solanum_tuberosum_'Doré').jpg?width=1024"},{"name":"Dublin's Famine Memorial","rarity":"uncommon","id":"dublin-s-famine-memorial","subtitle":"History & Lore","details":"Rowel Friers' gaunt bronze figures have stood on Dublin's Custom House Quay since 1997, walking toward the emigrant ships.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Famine%20Memorial%2C%20Custom%20House%20Quay%2C%20Dublin%2C%20Ireland%20-%20geograph.org.uk%20-%202561085.jpg?width=1024"},{"name":"Dum Aloo","rarity":"uncommon","id":"dum-aloo","subtitle":"Preparation","details":"Small potatoes deep-fried, then simmered low and slow in spiced gravy; a Kashmiri and Bengali favourite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aloor_dum_-_xen_suites.jpg?width=1024"},{"name":"Espirit","rarity":"uncommon","id":"espirit","subtitle":"Variety","details":"German variety with yellow skin and flesh, bred as a smooth table potato.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Espirit.jpg?width=1024"},{"name":"Fontane","rarity":"uncommon","id":"fontane","subtitle":"Variety","details":"Dutch variety grown all over Europe; a processing favorite turned into fries by the ton.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fontane_potato_SASA.jpg?width=1024"},{"name":"Garlic Fries","rarity":"uncommon","id":"garlic-fries","subtitle":"Chips & Fries","details":"Tossed with minced garlic and parsley the second they leave the fryer, so every fry gets coated.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pommes_Frites_-_Cafe_Orleans.jpg?width=1024"},{"name":"German Potato Salad","rarity":"uncommon","id":"german-potato-salad","subtitle":"Preparation","details":"Sliced potatoes in a warm bacon-vinegar dressing, the Swabian way — served warm, never with mayonnaise.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/(20251115)_Spreewälder_Kartoffelsalat_mit_Schinkenwurst_01.jpg?width=1024"},{"name":"Hash Brown Patties","rarity":"uncommon","id":"hash-brown-patties","subtitle":"Chips & Fries","details":"The shred, standardized: pressed into an oval patty so every drive-thru breakfast is identical, everywhere on Earth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2019-01-29_13_20_10_A_McDonald%27s_hash_brown_in_Chantilly%2C_Fairfax_County%2C_Virginia.jpg?width=1024"},{"name":"Home Guard","rarity":"uncommon","id":"home-guard","subtitle":"Variety","details":"Scottish variety from 1942, named for Britain's wartime Home Guard and bred to feed a nation at war.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Home_Guard_potato_SASA.jpg?width=1024"},{"name":"Imilla","rarity":"uncommon","id":"imilla","subtitle":"Variety","details":"Andean native potato; floury flesh and centuries of high-altitude farming behind it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Papa_Inilla.jpg?width=1024"},{"name":"Innovator","rarity":"uncommon","id":"innovator","subtitle":"Variety","details":"Dutch russet-skinned processing variety, bred by HZPC for the fry trade.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Innovator_potato_SASA.jpg?width=1024"},{"name":"Jazzy","rarity":"uncommon","id":"jazzy","subtitle":"Variety","details":"British variety sold as baby potatoes, with thin skins made for eating unpeeled.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jazzy_potatoes.jpg?width=1024"},{"name":"Karelia","rarity":"uncommon","id":"karelia","subtitle":"Variety","details":"Finnish variety named for the Karelia region; floury flesh that mashes beautifully.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kartoffelsorte_Karelia_Mehlig_kochend.jpg?width=1024"},{"name":"Kartoffelpuffer","rarity":"uncommon","id":"kartoffelpuffer","subtitle":"Preparation","details":"Germany's grated-potato fritters, eaten sweet with applesauce or savoury, a fixture of Christmas markets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20221217_potato_pancakes_sour_cream_Katowice_Panewniki.jpg?width=1024"},{"name":"Kestrel","rarity":"uncommon","id":"kestrel","subtitle":"Variety","details":"British variety with purple-blushed eyes and firm flesh, bred for the fresh market.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kestrelpotatoes.jpg?width=1024"},{"name":"Kroppkakor","rarity":"uncommon","id":"kroppkakor","subtitle":"Preparation","details":"Swedish potato dumplings filled with onion and pork or bacon, served with butter, cream and lingonberries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kroppkaka.jpg?width=1024"},{"name":"Latkes","rarity":"uncommon","id":"latkes","subtitle":"Preparation","details":"Grated potato and onion pancakes fried in oil for Hanukkah, celebrating the oil that burned for eight nights.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/00_Potato_Latkes.jpg?width=1024"},{"name":"Lefse","rarity":"uncommon","id":"lefse","subtitle":"Preparation","details":"A soft Norwegian flatbread of potato, flour and milk, rolled paper-thin and griddled; a Christmas tradition.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rolled_lefse.jpg?width=1024"},{"name":"Leyla","rarity":"uncommon","id":"leyla","subtitle":"Variety","details":"German early variety with smooth yellow skin and yellow flesh.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kartoffel_Leyla_02_(fcm).jpg?width=1024"},{"name":"Marabel","rarity":"uncommon","id":"marabel","subtitle":"Variety","details":"German variety with yellow skin and flesh; an early table potato across central Europe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kartoffeln_der_Sorte_Marabel.JPG?width=1024"},{"name":"Marfona","rarity":"uncommon","id":"marfona","subtitle":"Variety","details":"Dutch variety from 1975 with waxy yellow flesh; long a staple of British fish-and-chip shops' suppliers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Marfona_potato_SASA.jpg?width=1024"},{"name":"Masala Dosa","rarity":"uncommon","id":"masala-dosa","subtitle":"Preparation","details":"A crisp South Indian crepe wrapped around spiced potato masala, served with sambar and coconut chutney.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Masala_Dosa_02.jpg?width=1024"},{"name":"Melody","rarity":"uncommon","id":"melody","subtitle":"Variety","details":"Dutch variety with smooth yellow skin and a reputation as a reliable all-rounder.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/One_organic_Melody_potato_grown_in_Worcestershire_in_2015.jpg?width=1024"},{"name":"Nikujaga","rarity":"uncommon","id":"nikujaga","subtitle":"Preparation","details":"A Japanese home stew of meat, potatoes and onion simmered in sweetened soy; created for the Imperial Navy in the 1890s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Beef_and_potato_stew_in_Japanese-style_(6225795153).jpg?width=1024"},{"name":"Olivier Salad","rarity":"uncommon","id":"olivier-salad","subtitle":"Preparation","details":"Russia's celebration salad of potato, pickles, egg, peas and meat in mayonnaise, created in 1860s Moscow.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2023_Sałatka_jarzynowa_(1).jpg?width=1024"},{"name":"Papa Rellena","rarity":"uncommon","id":"papa-rellena","subtitle":"Preparation","details":"Peruvian mashed potato balls stuffed with seasoned beef, olives and egg, shaped like potatoes and deep-fried.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peru_PapasRellenas2.jpg?width=1024"},{"name":"Patat Speciaal","rarity":"uncommon","id":"patat-speciaal","subtitle":"Chips & Fries","details":"Dutch 'special' fries: mayonnaise, curry ketchup and raw onion in layers — a national institution in a paper tray.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Patat_speciaal_Leidschendam.JPG?width=1024"},{"name":"Patatas Revolconas","rarity":"uncommon","id":"patatas-revolconas","subtitle":"Preparation","details":"Ávila's mashed potatoes with paprika and crispy torreznos pork, stirred until they turn a deep red.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Patata_revolcona.jpg?width=1024"},{"name":"Peru's Potato Park","rarity":"uncommon","id":"peru-s-potato-park","subtitle":"History & Lore","details":"In Peru's Potato Park, Quechua farmers guard a living library of native potatoes, hundreds of varieties found nowhere else.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pisac%2C%20Cusco%2C%20Peru%20-%2017217251512.jpg?width=1024"},{"name":"Pommes Dauphine","rarity":"uncommon","id":"pommes-dauphine","subtitle":"Preparation","details":"Mashed potato mixed with choux pastry and deep-fried into crisp, airy puffs; named for a French dauphine.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Filetsteak_von_der_Färse_mit_Dauphine-Kartoffeln.jpg?width=1024"},{"name":"Pommes Sarladaises","rarity":"uncommon","id":"pommes-sarladaises","subtitle":"Preparation","details":"Potatoes sliced and cooked in duck or goose fat with garlic, from Sarlat in France's Dordogne; built for duck confit.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Confitdecanard.jpg?width=1024"},{"name":"Potato Cutter","rarity":"uncommon","id":"potato-cutter","subtitle":"Potato Thing","details":"One lever, one grid of blades, one firm push: a whole raw potato becomes a pile of fries-in-waiting in a single thunk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cutter%2C%20potato%20%28AM%202002.49.1-2%29.jpg?width=1024"},{"name":"Potato Digger","rarity":"uncommon","id":"potato-digger","subtitle":"Potato Thing","details":"Early diggers like this Triumph No. 5 did the lifting with a share and chain web, then left the picking to human hands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%22Triumph%22%20No.5%20Potato%20Digger%20-%20geograph.org.uk%20-%201343964.jpg?width=1024"},{"name":"Potato Doughnut","rarity":"uncommon","id":"potato-doughnut","subtitle":"Preparation","details":"The Spudnut: a doughnut made with mashed potato or potato starch instead of flour, lighter than it has any right to be.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Donat_Kentang.jpg?width=1024"},{"name":"Potato Flakes","rarity":"uncommon","id":"potato-flakes","subtitle":"Potato Thing","details":"Mash, drum-dried into flakes in the 1950s: just add hot water and butter. The potato became an instant, shelf-stable food.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pur%C3%A9%20de%20papas%20argentino%20%22Maggi%22%20%28instant%C3%A1neo%29.jpg?width=1024"},{"name":"Potato Flour","rarity":"uncommon","id":"potato-flour","subtitle":"Potato Thing","details":"Dried, ground, gluten-free: potato flour drinks up water like nothing else, keeping bakes moist and thickening sauces invisibly.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato%20flour2.jpg?width=1024"},{"name":"Potato Flowers at Court","rarity":"uncommon","id":"potato-flowers-at-court","subtitle":"History & Lore","details":"Louis XVI wore a potato flower in his buttonhole and Marie Antoinette wore one in her hair, making the tuber fashionable.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Louise%20Elisabeth%20Vig%C3%A9e-Lebrun%20-%20Marie-Antoinette%20dit%20%C2%AB%20%C3%A0%20la%20Rose%20%C2%BB%20-%20Google%20Art%20Project.jpg?width=1024"},{"name":"Potato Gnocchi","rarity":"uncommon","id":"potato-gnocchi","subtitle":"Preparation","details":"Italian dumplings of potato, flour and egg, rolled off a fork's tines; light ones float to the surface when done.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gnocchi_Carbonara_-_Moontone.jpg?width=1024"},{"name":"Potato Harvester","rarity":"uncommon","id":"potato-harvester","subtitle":"Potato Thing","details":"Tractor-drawn harvesters lift the crop on webs and belts, shaking off soil and stones before the spuds ever see a sack.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato%20harvester%20-%20geograph.org.uk%20-%20903402.jpg?width=1024"},{"name":"Potato Planter","rarity":"uncommon","id":"potato-planter","subtitle":"Potato Thing","details":"A tractor-drawn planter opens furrows, spaces seed potatoes like clockwork and covers them — a whole field sown in an afternoon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Villagers%20and%20potato%20planter%2C%20Klepachi%2C%20Belarus.jpg?width=1024"},{"name":"Potato Ricer","rarity":"uncommon","id":"potato-ricer","subtitle":"Potato Thing","details":"Squeezes cooked potato through tiny holes into rice-like grains — the secret behind cloud-smooth mash and featherlight gnocchi.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato-ricer.jpg?width=1024"},{"name":"Potato Sorting Machine","rarity":"uncommon","id":"potato-sorting-machine","subtitle":"Potato Thing","details":"Before cameras did the sorting, rollers, sieves and sharp eyes did. Vintage sorters like this one still tour steam fairs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20a%20potato%20sorting%20machine%20in%20the%20St%20Albans%20Steam%20and%20Country%20Show%20-%20geograph.org.uk%20-%204502899.jpg?width=1024"},{"name":"Potato Spinner","rarity":"uncommon","id":"potato-spinner","subtitle":"Potato Thing","details":"Invented in Scotland: spinning tines dig under the row and flick potatoes sideways into a neat line for the pickers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blackstone%20Digger%20potato%20spinner%20at%20Woolpit%202009.jpg?width=1024"},{"name":"Potato Stamps","rarity":"uncommon","id":"potato-stamps","subtitle":"Potato Thing","details":"Half a spud, a dab of paint: carving a potato into a stamp is many a child's first printing press.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato%20printing%20applying%20paint.jpg?width=1024"},{"name":"Potato Starch Cutlery","rarity":"uncommon","id":"potato-starch-cutlery","subtitle":"Potato Thing","details":"Knives and forks moulded from starch-based bioplastic — potato starch is a favourite feedstock — built to compost, not to last.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/BiodegradablePlasticUtensils1.jpg?width=1024"},{"name":"Potatoes Arrive in Europe","rarity":"uncommon","id":"potatoes-arrive-in-europe","subtitle":"History & Lore","details":"By 1573, a hospital in Seville, Spain was buying potatoes for its patients: among the first records of the tuber in Europe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Patio%20del%20Cardenal%2C%20Hospital%20de%20las%20Cinco%20Llagas%20%28Sevilla%29.jpg?width=1024"},{"name":"Potatoes on Frederick's Grave","rarity":"uncommon","id":"potatoes-on-frederick-s-grave","subtitle":"History & Lore","details":"Visitors to Sanssouci Palace still leave raw potatoes on Frederick the Great's grave — tribute to Prussia's Potato King.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20220810%20Schloss%20Sanssouci%2005.jpg?width=1024"},{"name":"Raspeball","rarity":"uncommon","id":"raspeball","subtitle":"Preparation","details":"Norwegian dumplings of grated potato and barley flour, also called komle or klubb depending on which fjord you ask.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Komlemiddag.jpg?width=1024"},{"name":"Red Pontiac","rarity":"uncommon","id":"red-pontiac","subtitle":"Variety","details":"Born in Florida in 1945 as a red-skinned mutant of Pontiac; an American garden classic ever since.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Red_Pontiac_potato_SASA.jpg?width=1024"},{"name":"Rooster","rarity":"uncommon","id":"rooster","subtitle":"Variety","details":"Bred in Ireland in 1990 at Teagasc Oak Park: red skin, yellow flesh, and good at absolutely everything.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rooster_potato_SASA.jpg?width=1024"},{"name":"Ruffled Chips","rarity":"uncommon","id":"ruffled-chips","subtitle":"Chips & Fries","details":"Deep ridges make them the sturdiest chip in the bowl, built to survive thick dips that snap lesser chips.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Opened_bag_of_Ruffles_All_Dressed_potato_chips_%28cropped%29.jpg?width=1024"},{"name":"Sarpo Mira","rarity":"uncommon","id":"sarpo-mira","subtitle":"Variety","details":"Hungarian variety from the Sárvári program, bred for exceptional resistance to late blight.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sarpo_Mira-2.JPG?width=1024"},{"name":"Shoestring Fries","rarity":"uncommon","id":"shoestring-fries","subtitle":"Chips & Fries","details":"Cut matchstick-thin — pommes allumettes in French — so they cook in minutes and come out almost entirely crunch.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Shoestring_fries%2C_garlic%2C_homemade_blue_cheese_dressing%2C_with_some_spicy_sauce.jpg?width=1024"},{"name":"Stamppot","rarity":"uncommon","id":"stamppot","subtitle":"Preparation","details":"The Dutch national winter dish: potatoes mashed with kale or other vegetables, served with smoked sausage and gravy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Boerenkool_met_worst.jpg?width=1024"},{"name":"The Drake Legend","rarity":"uncommon","id":"the-drake-legend","subtitle":"History & Lore","details":"An 1853 statue in Offenburg, Germany shows Francis Drake holding a potato plant: legend credits him with bringing it to Europe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Offenburg%20town%20hall.jpg?width=1024"},{"name":"The Highland Potato Famine","rarity":"uncommon","id":"the-highland-potato-famine","subtitle":"History & Lore","details":"From 1846 blight also emptied Scotland's Highland glens; relief meal kept crofters alive, and thousands emigrated overseas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fading%20ruins%20at%20Badbea%20Clearance%20Village%20-%20geograph.org.uk%20-%208379561.jpg?width=1024"},{"name":"The Idaho Potato","rarity":"uncommon","id":"the-idaho-potato","subtitle":"History & Lore","details":"Volcanic soil, sunny days and cool nights made Idaho russets famous; the state grows about a third of America's potatoes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Center%20pivot%20irrigation%20Idaho.jpg?width=1024"},{"name":"The Inca Potato Empire","rarity":"uncommon","id":"the-inca-potato-empire","subtitle":"History & Lore","details":"Potatoes fed the Inca Empire: farmed high in the Andes and stockpiled in state storehouses against years of famine.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ancient%20Inca%20terraces%20in%20the%20shape%20of%20the%20Millenium%20falcon%20from%20Star%20Wars....just%20kidding.%20Maras%2C%20Peru.jpg?width=1024"},{"name":"The International Potato Center","rarity":"uncommon","id":"the-international-potato-center","subtitle":"History & Lore","details":"Lima's International Potato Center, founded in 1971, guards thousands of potato varieties in the world's great spud genebank.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cip%20Handquarters%20%3D%20CIP%E6%9C%AC%E9%83%A8%E3%81%AE%E7%8E%84%E9%96%A2.jpg?width=1024"},{"name":"The Russian Potato Riots","rarity":"uncommon","id":"the-russian-potato-riots","subtitle":"History & Lore","details":"Forced potato-planting sparked riots among Russian state peasants in 1834 and again in 1840-44: revolts against a vegetable.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Old%20peasant%20with%20dagger%20and%20long%20smoking%20pipe%2C%20Mestia%2C%20Svanetia%2C%20Georgia%20%28Republic%29.jpg?width=1024"},{"name":"Vada Pav","rarity":"uncommon","id":"vada-pav","subtitle":"Preparation","details":"Mumbai's beloved 'burger': a batata vada in a bread roll with chutneys, selling by the million every day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aran_Vada_Pav_Mumbai.jpg?width=1024"},{"name":"Vivaldi","rarity":"uncommon","id":"vivaldi","subtitle":"Variety","details":"Dutch variety with smooth, creamy flesh; once marketed in Britain as a lighter, weight-watchers' potato.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vivaldi_potato_SASA.jpg?width=1024"},{"name":"Waffle Fries","rarity":"uncommon","id":"waffle-fries","subtitle":"Chips & Fries","details":"A ridged blade and a quarter-turn between slices makes the lattice — maximum crunch, with built-in pockets for dip.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Waffle_fry_%284532929501%29.jpg?width=1024"},{"name":"Warba","rarity":"uncommon","id":"warba","subtitle":"Variety","details":"Early North American variety with pink-blushed eyes; a spring 'new potato' favorite in British Columbia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2026-05-30_BC_Canada_grown,_Warba_new_potatoes_-_Victoria_BC_CAN.jpg?width=1024"},{"name":"Weinberger","rarity":"uncommon","id":"weinberger","subtitle":"Variety","details":"Austrian kipfler named Germany's Potato of the Year 2017, as the sign in its portrait records.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Weinberger.jpg?width=1024"},{"name":"'Famous Potatoes' Since 1937","rarity":"common","id":"famous-potatoes-since-1937","subtitle":"History & Lore","details":"The Idaho Potato Commission, founded in 1937, puts 'Famous Potatoes' on license plates — and sponsors Boise's Famous Idaho Potato Bowl.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2018%20Famous%20Idaho%20Potato%20Bowl.jpg?width=1024"},{"name":"Aloo Matar","rarity":"common","id":"aloo-matar","subtitle":"Preparation","details":"A homestyle North Indian curry of potatoes and green peas in a tomato-onion gravy, weeknight food at its finest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aalu_Matar_Curry.jpg?width=1024"},{"name":"Ambassador","rarity":"common","id":"ambassador","subtitle":"Variety","details":"Modern maincrop variety photographed for Scotland's national potato collection at SASA.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ambassador_potato_SASA.jpg?width=1024"},{"name":"American Potato Salad","rarity":"common","id":"american-potato-salad","subtitle":"Preparation","details":"Boiled potatoes in mayonnaise dressing with egg and celery; the mandatory guest at every American picnic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato_salad_(1).jpg?width=1024"},{"name":"Arizona","rarity":"common","id":"arizona","subtitle":"Variety","details":"Modern variety with smooth pale skin and white flesh, from the SASA national collection.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Arizona_potato_SASA.jpg?width=1024"},{"name":"Arsenal","rarity":"common","id":"arsenal","subtitle":"Variety","details":"Modern variety with round, pale tubers, photographed for the SASA national collection.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Arsenal_potato_SASA.jpg?width=1024"},{"name":"Augusta","rarity":"common","id":"augusta","subtitle":"Variety","details":"German table variety with yellow skin and pale yellow flesh, sold across central Europe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Basket_of_potatoes.jpg?width=1024"},{"name":"Axona","rarity":"common","id":"axona","subtitle":"Variety","details":"Red-skinned variety with white flesh, photographed for Scotland's SASA national collection.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Axona_potato_SASA.jpg?width=1024"},{"name":"Baccara","rarity":"common","id":"baccara","subtitle":"Variety","details":"German variety with smooth yellow skin; a general-purpose table potato.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Baccara.jpg?width=1024"},{"name":"Baked Potato","rarity":"common","id":"baked-potato","subtitle":"Preparation","details":"A whole potato baked until the skin crisps and the inside turns fluffy; split open and filled with butter and toppings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Baked_Potato_with_Mayonnaise.jpg?width=1024"},{"name":"BBQ Chips","rarity":"common","id":"bbq-chips","subtitle":"Chips & Fries","details":"Smoky, sweet and paprika-red — barbecue was one of the first flavors ever dusted onto a potato chip.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lay%E2%80%99s_Bar-B-Q_Potato_Chips_%288640643596%29.jpg?width=1024"},{"name":"Belana","rarity":"common","id":"belana","subtitle":"Variety","details":"German variety with oval yellow tubers; a modern all-rounder for boiling and roasting.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Belana_Kartoffeln.jpeg?width=1024"},{"name":"Blaue St. Galler","rarity":"common","id":"blaue-st-galler","subtitle":"Variety","details":"Swiss blue variety from St. Gallen; served boiled, its marbled blue flesh is the whole point.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blaue_St._Galler_2.jpg?width=1024"},{"name":"Boiled Potatoes","rarity":"common","id":"boiled-potatoes","subtitle":"Preparation","details":"Potatoes simmered in salted water and served plain with butter. Cooking stripped to its absolute minimum.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Grünkohl,_Pinkel,_Salzkartoffeln.jpg?width=1024"},{"name":"Bremner","rarity":"common","id":"bremner","subtitle":"Variety","details":"Scottish-bred variety with pale, round tubers, from the SASA national collection.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bremner_potato_SASA.jpg?width=1024"},{"name":"Bute","rarity":"common","id":"bute","subtitle":"Variety","details":"Named for the Isle of Bute; a pale-skinned variety in Scotland's national collection.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bute_potato_SASA.jpg?width=1024"},{"name":"Campina","rarity":"common","id":"campina","subtitle":"Variety","details":"German table variety with smooth yellow skin, sold in market crates across Germany.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kartoffel_Campina_01_(fcm).jpg?width=1024"},{"name":"Catherine the Great's Potato Decree","rarity":"common","id":"catherine-the-great-s-potato-decree","subtitle":"History & Lore","details":"In 1765 Catherine the Great's government pushed Russians to plant potatoes, even printing guides for wary peasants.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Argunov%20Catherine%20the%20Great.jpg?width=1024"},{"name":"Chip Butty","rarity":"common","id":"chip-butty","subtitle":"Chips & Fries","details":"Thick chips in a buttered bap with ketchup or brown sauce — the North of England's answer to the crisp sandwich.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chip_Muffin_2364555437.jpg?width=1024"},{"name":"Chitting Tray","rarity":"common","id":"chitting-tray","subtitle":"Potato Thing","details":"Gardeners 'chit' seed potatoes in trays, sprouting them in daylight indoors to steal a head start on spring.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chitted%20seed%20potatoes.jpg?width=1024"},{"name":"Churchill","rarity":"common","id":"churchill","subtitle":"Variety","details":"Modern variety with pale skin, pink-blushed eyes and white flesh, from the SASA collection.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Churchill_(2014)_potato_SASA.jpg?width=1024"},{"name":"Chuño for the Silver Mines","rarity":"common","id":"chuno-for-the-silver-mines","subtitle":"History & Lore","details":"The Spanish fed chuño to the Indigenous miners of Potosí, whose silver mines bankrolled an empire in the 1500s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cerro%20Rico%2C%20Potos%C3%AD%2C%20Bolivia.jpg?width=1024"},{"name":"Compass","rarity":"common","id":"compass","subtitle":"Variety","details":"Modern variety with yellow skin and deep yellow flesh, from the SASA collection.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Compass_potato_SASA.jpg?width=1024"},{"name":"Corinna","rarity":"common","id":"corinna","subtitle":"Variety","details":"German early variety with smooth oval tubers and yellow flesh.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kartoffel_Corinna_01_(fcm).jpg?width=1024"},{"name":"Crinkle-Cut Fries","rarity":"common","id":"crinkle-cut-fries","subtitle":"Chips & Fries","details":"The wavy cut adds crispy edges and grooves that trap salt and ketchup; it also keeps fries from going limp as fast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crinkle_cut_french_fries.jpg?width=1024"},{"name":"Dill Pickle Chips","rarity":"common","id":"dill-pickle-chips","subtitle":"Chips & Fries","details":"Briny and garlicky with a vinegar bite; beloved in Canada and anywhere pickles are a personality trait.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dill_pickle_chips.jpg?width=1024"},{"name":"Dolly","rarity":"common","id":"dolly","subtitle":"Variety","details":"Red-skinned variety with yellow flesh, photographed for the SASA national collection.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dolly_potato_SASA.jpg?width=1024"},{"name":"Domestication at Lake Titicaca","rarity":"common","id":"domestication-at-lake-titicaca","subtitle":"History & Lore","details":"Farmers near Lake Titicaca in Peru and Bolivia first domesticated the wild potato some 7,000 to 10,000 years ago.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bolivia%20-%20Inca%20terraces%2C%20on%20the%20shores%20of%20Lake%20Titicaca.jpg?width=1024"},{"name":"Edony","rarity":"common","id":"edony","subtitle":"Variety","details":"Modern variety with golden skin and deep yellow flesh, from the SASA collection.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Edony_potato_SASA.jpg?width=1024"},{"name":"Electra","rarity":"common","id":"electra","subtitle":"Variety","details":"Large oval variety with pale yellow skin, photographed for the SASA national collection.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Electra_potato_SASA.jpg?width=1024"},{"name":"Ellie","rarity":"common","id":"ellie","subtitle":"Variety","details":"Modern variety with yellow skin and flesh, from Scotland's SASA national collection.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ellie_potato_SASA.jpg?width=1024"},{"name":"Ewelina","rarity":"common","id":"ewelina","subtitle":"Variety","details":"Polish variety with yellow skin and cream flesh, bred for eastern European soils.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ewelina.jpg?width=1024"},{"name":"Filea","rarity":"common","id":"filea","subtitle":"Variety","details":"German variety with long oval tubers and yellow flesh.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Filea.jpg?width=1024"},{"name":"Finka","rarity":"common","id":"finka","subtitle":"Variety","details":"German variety with yellow skin; a firm-fleshed table potato.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Finka_(retuschiert).jpg?width=1024"},{"name":"French Fries","rarity":"common","id":"french-fries","subtitle":"Chips & Fries","details":"France and Belgium still feud over who invented them; Belgian lore says river villagers fried potatoes when the fish froze in the 1680s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/French_Fries_with_Ketchup_01.jpg?width=1024"},{"name":"Gael","rarity":"common","id":"gael","subtitle":"Variety","details":"Knobbly yellow variety with deep yellow flesh, photographed for the SASA collection.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gael_potato_SASA.jpg?width=1024"},{"name":"Gala","rarity":"common","id":"gala","subtitle":"Variety","details":"German variety from 1992; one of the most planted table potatoes in Germany today.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kartoffel_Gala_02_(fcm).jpg?width=1024"},{"name":"Gatsby","rarity":"common","id":"gatsby","subtitle":"Variety","details":"Smooth, pale-skinned modern variety from Scotland's SASA national collection.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gatsby_potato_SASA.jpg?width=1024"},{"name":"Gerard's Herball, 1597","rarity":"common","id":"gerard-s-herball-1597","subtitle":"History & Lore","details":"London herbalist John Gerard grew potatoes in his own garden and pictured them in his 1597 Herball, an English first.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/John%20Gerard-Virginia%20Potato.jpg?width=1024"},{"name":"Golden Beauty","rarity":"common","id":"golden-beauty","subtitle":"Variety","details":"Golden-skinned modern variety photographed for the SASA national collection.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Golden_Beauty_potato_SASA.jpg?width=1024"},{"name":"Golden Sun","rarity":"common","id":"golden-sun","subtitle":"Variety","details":"Modern variety true to its name: golden skin over pale yellow flesh, from the SASA collection.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Golden_Sun_potato_SASA.jpg?width=1024"},{"name":"Gwenne","rarity":"common","id":"gwenne","subtitle":"Variety","details":"French-bred salad variety with pale skin and firm flesh, from the SASA collection.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gwenne_potato_SASA.jpg?width=1024"},{"name":"Hand Potato Planter","rarity":"common","id":"hand-potato-planter","subtitle":"Potato Thing","details":"Stomp the blade, squeeze the handle, drop a seed potato down the tube. This jab planter still sows small farms worldwide.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Manual%20potato%20planter.jpg?width=800"},{"name":"Hash Browns","rarity":"common","id":"hash-browns","subtitle":"Chips & Fries","details":"Shredded potatoes fried crisp and golden; they've anchored American diner breakfasts since menus first listed them in the 1890s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hash_Browns.jpg?width=1024"},{"name":"Home Fries","rarity":"common","id":"home-fries","subtitle":"Chips & Fries","details":"Diner bedrock: diced or sliced potatoes pan-fried with onion and peppers, served next to eggs at breakfast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Flickr_lifeontheedge_3672951574--Home_fried_potatoes.jpg?width=1024"},{"name":"Idaho's First Potatoes","rarity":"common","id":"idaho-s-first-potatoes","subtitle":"History & Lore","details":"Missionary Henry Spalding planted Idaho's first potatoes at his Lapwai mission in 1836, alongside the Nez Perce.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Henry%20Harmon%20Spalding%2C%20ca.%201880%20-%20DPLA%20-%202075ec9d0c79b6f234e42c586c544553.jpg?width=1024"},{"name":"Infinity","rarity":"common","id":"infinity","subtitle":"Variety","details":"Red-skinned variety with white flesh, photographed for the SASA national collection.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Infinity_potato_SASA.jpg?width=1024"},{"name":"International Year of the Potato","rarity":"common","id":"international-year-of-the-potato","subtitle":"History & Lore","details":"The United Nations declared 2008 the International Year of the Potato, honouring the tuber that feeds billions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Patates.jpg?width=1024"},{"name":"Ivory Russet","rarity":"common","id":"ivory-russet","subtitle":"Variety","details":"Russet-skinned variety with white flesh, photographed for the SASA national collection.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ivory_Russet_potato_SASA.jpg?width=1024"},{"name":"Jalapeño Chips","rarity":"common","id":"jalapeno-chips","subtitle":"Chips & Fries","details":"Kettle chips are the usual canvas for jalapeño heat — thick enough to carry real pepper burn.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zapp%27s_Potato_Chips_-_Hotter_%27N_Hot_Jalapeno%2C_Voodoo%2C_Regular_Flavor.jpg?width=1024"},{"name":"Japanese Potato Salad","rarity":"common","id":"japanese-potato-salad","subtitle":"Preparation","details":"Japan's potato salad is partly mashed, with cucumber, carrot and ham in Kewpie mayonnaise; an izakaya staple.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Another_batch_of_potato_salad,_this_time_with_red_onions_and_sun_dried_tomatoes_and_fish_sausage_魚肉ソーセージ入りポテトサラダその2。今回は赤玉ねぎとサンドライドトマト入り.jpg?width=1024"},{"name":"Korokke","rarity":"common","id":"korokke","subtitle":"Preparation","details":"Japanese croquettes of mashed potato and minced meat in panko crumbs, a Meiji-era take on the French original.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Croquette-1.jpg?width=1024"},{"name":"Kugelis","rarity":"common","id":"kugelis","subtitle":"Preparation","details":"A Lithuanian baked pudding of grated potato, bacon, milk, onion and egg, sliced and served with sour cream.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bulvių_plokštainis.jpg?width=1024"},{"name":"Kuku Sibzamini","rarity":"common","id":"kuku-sibzamini","subtitle":"Preparation","details":"Persian potato patties with egg and turmeric, pan-fried and eaten in sandwiches with pickles and tomato.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/کوکو_سیب_زمینی.jpg?width=1024"},{"name":"Kumpir","rarity":"common","id":"kumpir","subtitle":"Preparation","details":"Turkey's loaded baked potato: the flesh whipped with butter and cheese, then buried under a salad bar of toppings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kumpir_-_Turkish_Cuisine.jpg?width=1024"},{"name":"Laura","rarity":"common","id":"laura","subtitle":"Variety","details":"German red-skinned variety with deep yellow flesh, named simply Laura.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Laura_(odrůda_brambor).jpg?width=1024"},{"name":"Llapingachos","rarity":"common","id":"llapingachos","subtitle":"Preparation","details":"Ecuadorian fried potato patties stuffed with cheese, served with peanut sauce, sausage and a fried egg.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Llapingachos-_gebratene_Kartoffelpuffer.jpg?width=1024"},{"name":"Lyonnaise Potatoes","rarity":"common","id":"lyonnaise-potatoes","subtitle":"Preparation","details":"Sliced potatoes pan-fried with onions in butter and parsley, from Lyon, France's self-declared food capital.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lyonnaise_potatoes_Fresh_Buffet_Solaire_23_January_2025_Filipinas15.jpg?width=1024"},{"name":"Mashed Potatoes","rarity":"common","id":"mashed-potatoes","subtitle":"Preparation","details":"Boiled potatoes crushed with butter and milk or cream. The default setting for potatoes across much of the Western world.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20230120_Polish_cuisine_Hard-boiled_eggs_horseradish_sauce_pickled_courgettes_Mashed_potatoes_Panewniki.jpg?width=1024"},{"name":"Mokimo","rarity":"common","id":"mokimo","subtitle":"Preparation","details":"A Kenyan mash of potatoes with greens, peas and maize, a Kikuyu staple served at gatherings with nyama choma.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mukimo_&_Beef_Stew.jpg?width=1024"},{"name":"Moor Sieglinde","rarity":"common","id":"moor-sieglinde","subtitle":"Variety","details":"Sieglinde grown in black moor soil; German markets sell it as a regional specialty tuber.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Moor_Sieglinde_(Kartoffel).JPG?width=1024"},{"name":"Nightshade Fears","rarity":"common","id":"nightshade-fears","subtitle":"History & Lore","details":"The potato is kin to deadly nightshade, so many Europeans feared it was poison — and clergy noted it is never mentioned in the Bible.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Atropa%20belladonna%20003.JPG?width=1024"},{"name":"Nishiyutaka","rarity":"common","id":"nishiyutaka","subtitle":"Variety","details":"Japanese variety from Nagasaki breeding, with smooth skin and pale flesh.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato_cv_Nishiyutaka.jpg?width=1024"},{"name":"Opperdoezer Ronde","rarity":"common","id":"opperdoezer-ronde","subtitle":"Variety","details":"Dutch village heirloom from Opperdoes, protected by EU status; harvested young and eaten in spring.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Opperdoezer_Ronde.jpg?width=1024"},{"name":"Parel","rarity":"common","id":"parel","subtitle":"Variety","details":"Dutch variety whose name means 'pearl'; small, round and pale-fleshed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aardappel_'Parel'_(Solanum_tuberosum).jpg?width=1024"},{"name":"Peter the Great's Sack of Potatoes","rarity":"common","id":"peter-the-great-s-sack-of-potatoes","subtitle":"History & Lore","details":"In the late 1690s Peter the Great shipped a sack of potatoes home from Holland: Russia's introduction to the tuber.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bust%20of%20Peter%20the%20Great%20by%20Marie-Anne%20Collot%201770.JPG?width=1024"},{"name":"Pierogi","rarity":"common","id":"pierogi","subtitle":"Preparation","details":"Polish dumplings; the ruskie filling of potato and curd cheese is the most beloved of them all.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Food_in_Lichen_Stary_(pierogi_ruskie,_dumplings).jpg?width=1024"},{"name":"Plain Potato Chips","rarity":"common","id":"plain-potato-chips","subtitle":"Chips & Fries","details":"Legend credits a Saratoga Springs cook in 1853; paper-thin, fried crisp, salted — every flavor since is commentary.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato-Chips.jpg?width=1024"},{"name":"Potato Bread","rarity":"common","id":"potato-bread","subtitle":"Preparation","details":"Bread in which cooked potato replaces part of the flour, keeping the loaf soft and moist for days.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Homemade_potato_bread,_half.jpg?width=1024"},{"name":"Potato Chips","rarity":"common","id":"potato-chips","subtitle":"Preparation","details":"Paper-thin potato slices fried until crisp. Legend credits a Saratoga Springs chef in 1853, spite-cooking for a picky guest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A_bowl_of_snacks.jpg?width=1024"},{"name":"Potato Crate","rarity":"common","id":"potato-crate","subtitle":"Potato Thing","details":"Slatted wooden crates stack high, let air through and keep the harvest bruise-free from field to market stall.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato%20crates.%20-%20geograph.org.uk%20-%20249543.jpg?width=1024"},{"name":"Potato Croquettes","rarity":"common","id":"potato-croquettes","subtitle":"Preparation","details":"Mashed potato, sometimes with cheese or ham, crumbed and deep-fried into golden torpedoes. Leftovers, promoted.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brisket_Potato_Croquette.jpg?width=1024"},{"name":"Potato Grater","rarity":"common","id":"potato-grater","subtitle":"Potato Thing","details":"A wall of sharp holes standing between you and latkes, rösti and dumplings. Donated knuckle skin is traditionally included.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kartoffelreibe.jpg?width=1024"},{"name":"Potato Grow Bag","rarity":"common","id":"potato-grow-bag","subtitle":"Potato Thing","details":"No plot? No problem. Tip a grow bag onto the patio, rummage through the compost, and dinner falls out.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato%20bag%20cultivation.JPG?width=1024"},{"name":"Potato Masher","rarity":"common","id":"potato-masher","subtitle":"Potato Thing","details":"Boiled potatoes fear it. Zigzag wire mashers have been flattening spuds since the 1800s without a single design improvement.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato%20Masher.jpg?width=1024"},{"name":"Potato Pancakes","rarity":"common","id":"potato-pancakes","subtitle":"Preparation","details":"Grated potato bound with egg and flour, pan-fried crisp at the edges. A staple from Ireland to Korea in local dialects.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/020260516_141010_Potato_pancakes_with_meat_goulash.jpg?width=1024"},{"name":"Potato Peeler","rarity":"common","id":"potato-peeler","subtitle":"Potato Thing","details":"The swivel blade floats over bumps and takes the skin off in thin ribbons. Every kitchen drawer contains exactly one, somewhere.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peeler%2001%20Pengo.jpg?width=1024"},{"name":"Potato Pete","rarity":"common","id":"potato-pete","subtitle":"History & Lore","details":"Britain's wartime Potato Pete, a Ministry of Food cartoon character, urged families to fill up on spuds and save bread.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/I%27m%20a%20Protective%20Food%20-%20Says%20Potato%20Pete%20Art.IWMPST20603.NOBORDER.jpg?width=1024"},{"name":"Potato Plough","rarity":"common","id":"potato-plough","subtitle":"Potato Thing","details":"Its double mouldboard both throws up the ridge potatoes grow in and, come harvest, splits that ridge open again.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Matthew%20Wech%27s%20potato%20plough%2C%20Puhoi%20Heritage%20Museum.jpg?width=1024"},{"name":"Potato Sack","rarity":"common","id":"potato-sack","subtitle":"Potato Thing","details":"A burlap sack swallows roughly 50 pounds of spuds and has done so for centuries. Also doubles as elite racing attire.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Irish%20potatoes%20in%20a%20sack%20in%20a%20market.jpg?width=800"},{"name":"Potato Soup","rarity":"common","id":"potato-soup","subtitle":"Preparation","details":"Potatoes simmered and partly crushed into a thick, buttery soup. Every cold country has its own sworn version.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A_bowl_of_potato_soup.jpg?width=1024"},{"name":"Potato Starch","rarity":"common","id":"potato-starch","subtitle":"Potato Thing","details":"Washed out of grated spuds, this powder thickens sauces, crisps coatings, stiffens laundry and glues envelopes. Busy molecule.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato%20Starch.JPG?width=1024"},{"name":"Potato Sticks","rarity":"common","id":"potato-sticks","subtitle":"Chips & Fries","details":"Canned matchstick potato crisps: tiny, salty and engineered to be eaten by the handful, never one at a time.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/8087Foods_and_goods_in_Bulacan_04.jpg?width=1024"},{"name":"Potato Washer","rarity":"common","id":"potato-washer","subtitle":"Potato Thing","details":"A mobile rig of drums and water jets that scrubs field-fresh potatoes before grading — a car wash that makes house calls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mobile%20Potato%20Washing%20-%20geograph.org.uk%20-%202098199.jpg?width=800"},{"name":"Potato Wedges","rarity":"common","id":"potato-wedges","subtitle":"Chips & Fries","details":"Unpeeled and cut into chunky lengthwise wedges, usually seasoned with paprika — too big to be fries, too proud to be roasties.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/KFC_Seasoned_Potato_Wedges_%2816987783077%29.jpg?width=1024"},{"name":"Potatoes au Gratin","rarity":"common","id":"potatoes-au-gratin","subtitle":"Preparation","details":"Sliced potatoes baked in cheese sauce under a browned crust; the American answer to the Dauphinois debate.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato_gratin_after_baking.jpg?width=1024"},{"name":"Princess","rarity":"common","id":"princess","subtitle":"Variety","details":"German variety with yellow skin and deep yellow flesh, bred as an early salad potato.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potatoe_var_Princess.jpg?width=1024"},{"name":"Quarta","rarity":"common","id":"quarta","subtitle":"Variety","details":"German variety with red-blushed eyes and yellow flesh; a common sight in German markets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Quarta.jpg?width=1024"},{"name":"Ranger Russet","rarity":"common","id":"ranger-russet","subtitle":"Variety","details":"American russet from 1991, bred in Idaho as a modern successor in the Russet Burbank mold.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ranger_Russet_potato_SASA.jpg?width=1024"},{"name":"Repeal of the Corn Laws","rarity":"common","id":"repeal-of-the-corn-laws","subtitle":"History & Lore","details":"Ireland's blight pushed Prime Minister Robert Peel to repeal the Corn Laws in 1846: it split his party and ended his career.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Portrait%20of%20Sir%20Robert%20Peel%20%284671768%29.jpg?width=1024"},{"name":"Rewena Bread","rarity":"common","id":"rewena-bread","subtitle":"Preparation","details":"A Māori sourdough potato bread from New Zealand, raised by a fermented potato starter called a bug.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rewena.jpg?width=1024"},{"name":"Roast Potatoes","rarity":"common","id":"roast-potatoes","subtitle":"Preparation","details":"Chunks of potato roasted in hot fat until the edges crisp and the centres stay fluffy; the centrepiece of a Sunday roast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Roast_beef_Sunday_roast_at_The_Stag,_Little_Easton,_Essex,_England.jpg?width=1024"},{"name":"Rosalind","rarity":"common","id":"rosalind","subtitle":"Variety","details":"British red-skinned variety with yellow flesh, bred for the fresh market.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Solanum_tuberosum_Rosalind20100329_01.jpg?width=1024"},{"name":"Rote Emma","rarity":"common","id":"rote-emma","subtitle":"Variety","details":"German red-skinned variety sold in market baskets; its cousin Rote Emmalie has pink flesh.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rote_Emma_(Kartoffel).jpg?width=1024"},{"name":"Rumbledethumps","rarity":"common","id":"rumbledethumps","subtitle":"Preparation","details":"A Scottish Borders bake of potato, cabbage and onion mashed, topped with cheese and baked until golden.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rumbledethumps.JPG?width=1024"},{"name":"Salchipapas","rarity":"common","id":"salchipapas","subtitle":"Preparation","details":"Peruvian street food of fries tossed with sliced fried sausage, served with a rainbow of sauces.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Salchipapa_Costeña.jpg?width=1024"},{"name":"Salt & Pepper Chips","rarity":"common","id":"salt-pepper-chips","subtitle":"Chips & Fries","details":"The Chinese-takeaway chips from Liverpool: fries wok-tossed with chili, peppers, onion and salt-and-pepper seasoning.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Salt_and_Pepper_Chips.jpg?width=1024"},{"name":"Salt & Vinegar Chips","rarity":"common","id":"salt-vinegar-chips","subtitle":"Chips & Fries","details":"Sharp, lip-stinging malt vinegar tang — a British crisp-aisle cornerstone since flavored crisps began in the 1950s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zapp%27s_Potato_Chips_-_Salt_%26_Vinegar.jpg?width=1024"},{"name":"Samosa","rarity":"common","id":"samosa","subtitle":"Preparation","details":"A crisp pastry triangle with a spiced potato and pea heart, fried across South Asia and half the world beyond.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dal_Samosa.jpg?width=1024"},{"name":"Schupfnudeln","rarity":"common","id":"schupfnudeln","subtitle":"Preparation","details":"Southern German finger-shaped potato noodles, boiled then often crisped in butter and served with sauerkraut.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Schupfnudeln_mit_Sauerkraut.jpg?width=1024"},{"name":"Shepherd's Pie","rarity":"common","id":"shepherd-s-pie","subtitle":"Preparation","details":"Minced lamb in gravy under a mashed potato crust, baked until the peaks brown. With beef, it becomes cottage pie.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Australian_cottage_pie.jpg?width=1024"},{"name":"Sieglinde","rarity":"common","id":"sieglinde","subtitle":"Variety","details":"Germany's oldest protected variety name (1935); here it is served tiny, in vincotto syrup, Sicilian style.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Patata_sieglinde_nel_vincotto.jpg?width=1024"},{"name":"Silesian Dumplings","rarity":"common","id":"silesian-dumplings","subtitle":"Preparation","details":"Polish kluski śląskie: mashed potato and potato flour dumplings, each pressed with a dimple to hold the sauce.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/\"Gebratenes_Kaninchen\"_2013.JPG?width=1024"},{"name":"Smashed Potatoes","rarity":"common","id":"smashed-potatoes","subtitle":"Preparation","details":"Boiled whole, flattened with the palm or a glass, then roasted or fried so every craggy edge goes crisp.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Baked_Smashed_Potatoes.JPG?width=1024"},{"name":"Solara","rarity":"common","id":"solara","subtitle":"Variety","details":"German variety with smooth yellow skin and flesh; a salad and boiling potato.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Solara.jpg?width=1024"},{"name":"Sour Cream & Onion Chips","rarity":"common","id":"sour-cream-onion-chips","subtitle":"Chips & Fries","details":"One of the first flavored chips ever sold, from the 1950s; the green flecks are parsley, not evidence.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lay%27s_Sour_Cream_and_Onion_Potato_Chips%2C_Canada%2C_2026-02-15.jpg?width=1024"},{"name":"Spud Gun","rarity":"common","id":"spud-gun","subtitle":"Potato Thing","details":"The 1940s pocket toy: jam the tip into a raw potato, snap off a plug, squeeze — compressed air fires it. Harmless. Mostly.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spud%20Gun.jpg?width=1024"},{"name":"Spunta","rarity":"common","id":"spunta","subtitle":"Variety","details":"Dutch variety from 1968; one of the most exported potatoes in the world, huge across the Mediterranean.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spunta-6824-9752.jpg?width=1024"},{"name":"Steak Fries","rarity":"common","id":"steak-fries","subtitle":"Chips & Fries","details":"The heavyweight cut: thick slabs with fluffy middles, built to survive steak juice, gravy and aggressive dipping.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Steak_and_fries.jpeg?width=1024"},{"name":"Stovies","rarity":"common","id":"stovies","subtitle":"Preparation","details":"A Scottish stew of potatoes slowly cooked with onion and leftover roast meat in its own dripping.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Stovies.JPG?width=1024"},{"name":"Sweet Potato Chips","rarity":"common","id":"sweet-potato-chips","subtitle":"Chips & Fries","details":"Sliced thin and fried until the edges curl; sweeter and earthier than the classic, no dip required.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sweet_potato_chips_in_Shandong%2C_china.jpg?width=1024"},{"name":"Sweet Potato Fries","rarity":"common","id":"sweet-potato-fries","subtitle":"Chips & Fries","details":"Their natural sugars caramelize faster than regular fries. Botanically not potatoes at all, but the menu has spoken.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sweet_Potato_Fries_3.jpg?width=1024"},{"name":"Tattie Scones","rarity":"common","id":"tattie-scones","subtitle":"Preparation","details":"Scottish griddle scones of mashed potato and flour, fried in the breakfast pan and folded into quarters.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potato_scone_with_vegetable_bake.jpg?width=1024"},{"name":"The Colorado Potato Beetle","rarity":"common","id":"the-colorado-potato-beetle","subtitle":"History & Lore","details":"This beetle swapped wild nightshades for potatoes near Omaha in 1859 and marched east, reaching the Atlantic Coast by 1874.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Colorado%20potato%20beetle.jpg?width=1024"},{"name":"The Isojoki Peeling Marathon","rarity":"common","id":"the-isojoki-peeling-marathon","subtitle":"History & Lore","details":"In 1984, villagers in Isojoki, Finland peeled potatoes for 1,218 hours — over 10 tonnes — setting a Guinness record.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Isojoki%20municipal%20border%20sign%2020200730.jpg?width=1024"},{"name":"The Parson Who Saw It First","rarity":"common","id":"the-parson-who-saw-it-first","subtitle":"History & Lore","details":"In 1846 clergyman-botanist Miles Berkeley argued the mould on blighted leaves was the cause, not the result. He was doubted.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Portret%20van%20Miles%20Joseph%20Berkeley%2C%20RP-F-2001-7-349-5.jpg?width=1024"},{"name":"The Potatoes of Chiloé","rarity":"common","id":"the-potatoes-of-chiloe","subtitle":"History & Lore","details":"The world's main potato descends from tubers of Chile's Chiloé Archipelago, grown there long before Spanish ships arrived.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chiloe%20-papas%20chilotas.jpg?width=1024"},{"name":"The Raleigh Legend","rarity":"common","id":"the-raleigh-legend","subtitle":"History & Lore","details":"Legend says Walter Raleigh planted Ireland's first potatoes near Youghal in the 1580s. Historians doubt it; Ireland kept the story.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Portrait%20of%20Sir%20Walter%20Raleigh%20%284671846%29.jpg?width=1024"},{"name":"The Word 'Potato'","rarity":"common","id":"the-word-potato","subtitle":"History & Lore","details":"'Potato' comes from Spanish 'patata', borrowed from Taíno 'batata' — the sweet potato's name, stuck onto the wrong tuber.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aardappel%20%28Solanum%20tuberosum%29%20aerde%20appelen.%20Arachidna%20theophrasti%20Tartouffani.%20pommes%20de%20terre.%20%28titel%20op%20object%29%2C%20RP-T-BR-2017-1-9-74.jpg?width=1024"},{"name":"Truffle Fries","rarity":"common","id":"truffle-fries","subtitle":"Chips & Fries","details":"Finished with truffle oil and parmesan. The 'truffle' is usually oil, not actual truffle — nobody at the table minds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Truffle_oil_french_fries_%2833024792848%29.jpg?width=1024"},{"name":"Twice-Baked Potatoes","rarity":"common","id":"twice-baked-potatoes","subtitle":"Preparation","details":"Baked potatoes hollowed out, the flesh mashed with cheese and cream, restuffed into the skins and baked a second time.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Twice_baked_potato.JPG?width=1024"},{"name":"Wahou","rarity":"common","id":"wahou","subtitle":"Variety","details":"French variety with two-tone skin — part yellow, part chestnut-brown — and pale flesh.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kartoffeln_Sorte_Wahou.jpg?width=1024"},{"name":"Wavy Chips","rarity":"common","id":"wavy-chips","subtitle":"Chips & Fries","details":"Wide, lazy waves instead of tight ridges — the middle path between a flat chip and a ruffle, made famous by Lay's Wavy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wavy_potato_chips.jpg?width=1024"}]});
